package io.artio.api.inventory;

import io.artio.api.catalog.CatalogNotFoundException;
import io.artio.inventory.*; import io.artio.inventory.ports.*; import io.artio.kernel.Quantity;
import java.math.BigDecimal; import java.util.List; import java.util.UUID; import java.time.Duration; import java.time.Instant;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;

@Service @Transactional
public class InventoryApplicationService {
    private final WarehouseRepository warehouses; private final StockRepository stock; private final ReservationRepository reservations; private final LowStockPolicyRepository lowStockPolicies; private final Duration reservationTtl;
    public InventoryApplicationService(WarehouseRepository warehouses,StockRepository stock,ReservationRepository reservations,LowStockPolicyRepository lowStockPolicies,@Value("${artio.inventory.reservation-ttl:PT30M}") Duration reservationTtl){this.warehouses=warehouses;this.stock=stock;this.reservations=reservations;this.lowStockPolicies=lowStockPolicies;if(reservationTtl.isZero()||reservationTtl.isNegative())throw new IllegalArgumentException("Reservation TTL must be positive");this.reservationTtl=reservationTtl;}
    @Transactional(readOnly=true) public List<WarehouseView> warehouses(){return warehouses.findAll().stream().map(WarehouseView::from).toList();}
    public WarehouseView createWarehouse(WarehouseRequest r){var w=Warehouse.create(new WarehouseId(UUID.randomUUID()),r.code(),r.name(),r.location());warehouses.save(w);return WarehouseView.from(w);}
    public WarehouseView setWarehouseActive(UUID id,boolean active){var w=warehouse(id);w.setActive(active);warehouses.save(w);return WarehouseView.from(w);}
    @Transactional(readOnly=true) public List<StockView> stockByWarehouse(UUID warehouse){warehouse(warehouse);return stock.findByWarehouse(new WarehouseId(warehouse)).stream().map(StockView::from).toList();}
    @Transactional(readOnly=true) public List<StockView> stockBySellable(UUID sellable){return stock.findBySellable(sellable).stream().map(StockView::from).toList();}
    @Transactional(readOnly=true) public List<LowStockView> lowStock(){return lowStockPolicies.findLowStock().stream().map(row->new LowStockView(row.warehouseId(),row.sellableId(),row.available(),row.threshold())).toList();}
    public LowStockPolicyView setLowStockPolicy(UUID warehouseId,UUID sellableId,BigDecimal threshold,boolean active){warehouse(warehouseId);var current=lowStockPolicies.findByWarehouseAndSellable(warehouseId,sellableId);var policy=new LowStockPolicy(current.map(LowStockPolicy::id).orElseGet(UUID::randomUUID),new WarehouseId(warehouseId),sellableId,threshold,active);lowStockPolicies.save(policy);return LowStockPolicyView.from(policy);}
    @Transactional(readOnly=true) public List<LowStockPolicyView> lowStockPolicies(UUID warehouseId){warehouse(warehouseId);return lowStockPolicies.findByWarehouse(warehouseId).stream().map(LowStockPolicyView::from).toList();}
    public StockView receive(UUID warehouse,UUID sellable,BigDecimal quantity){return receive(warehouse,sellable,quantity,"Stock receipt",null);}
    public StockView receive(UUID warehouse,UUID sellable,BigDecimal quantity,String reason,UUID actorId){warehouse(warehouse);var level=stock.lockOrCreate(new WarehouseId(warehouse),sellable);level.receive(new Quantity(quantity));stock.save(level,reason,actorId);return StockView.from(level);}
    public StockView adjust(UUID warehouse,UUID sellable,BigDecimal onHand){return adjust(warehouse,sellable,onHand,"Manual stock correction",null);}
    public StockView adjust(UUID warehouse,UUID sellable,BigDecimal onHand,String reason,UUID actorId){warehouse(warehouse);var level=stock.lockOrCreate(new WarehouseId(warehouse),sellable);level.adjustTo(new Quantity(onHand));stock.save(level,reason,actorId);return StockView.from(level);}
    @Transactional(readOnly=true) public List<StockMovement> movements(UUID warehouse,UUID sellable,int limit){if(limit<1||limit>200)throw new IllegalArgumentException("Movement limit must be between 1 and 200");warehouse(warehouse);return stock.findMovements(warehouse,sellable,limit);}
    public ReservationView reserve(ReserveRequest r){var warehouse=warehouse(r.warehouseId());if(!warehouse.isActive())throw new IllegalStateException("Inactive warehouse cannot accept reservations");var warehouseId=warehouse.getId();var level=stock.lockOrCreate(warehouseId,r.sellableId());var previous=reservations.findByOrderAndWarehouseAndSellable(r.orderId(),warehouseId,r.sellableId());if(previous.isPresent()){var existing=previous.get();if(existing.getState()==ReservationState.RESERVED&&existing.getQuantity().compareTo(r.quantity())==0)return ReservationView.from(existing);throw new IllegalStateException("Order already has a reservation for this sellable and warehouse");}var reservation=Reservation.reserve(new ReservationId(UUID.randomUUID()),r.orderId(),warehouseId,r.sellableId(),new Quantity(r.quantity()),Instant.now().plus(reservationTtl));level.reserve(new Quantity(r.quantity()));stock.save(level);reservations.save(reservation);return ReservationView.from(reservation);}
    public ReservationView allocate(UUID id){return transition(id,true);}
    public ReservationView allocate(UUID orderId,UUID sellableId,BigDecimal quantity){
        var candidates=reservations.findByOrder(orderId).stream().filter(r->r.getSellableId().equals(sellableId)&&r.remainingQuantity().signum()>0).toList();
        if(candidates.isEmpty())throw new CatalogNotFoundException("No outstanding stock reservation exists for this order item");
        BigDecimal remaining=quantity;
        for(var candidate:candidates){if(remaining.signum()==0)break;stock.lockOrCreate(candidate.getWarehouseId(),candidate.getSellableId());var current=reservations.findById(candidate.getId()).orElseThrow();
            BigDecimal allocated=remaining.min(current.remainingQuantity());current.allocate(allocated);var level=stock.lockOrCreate(current.getWarehouseId(),current.getSellableId());level.allocate(new Quantity(allocated));stock.save(level);reservations.save(current);remaining=remaining.subtract(allocated);}
        if(remaining.signum()>0)throw new IllegalStateException("Shipment quantity exceeds reserved stock");
        return ReservationView.from(reservations.findById(candidates.getFirst().getId()).orElseThrow());
    }
    public ReservationView release(UUID id){return transition(id,false);}
    public int expireDueReservations(Instant now,int limit){if(limit<1||limit>1000)throw new IllegalArgumentException("Expiry batch size must be between 1 and 1000");var expired=reservations.findExpired(now,limit);int released=0;for(var candidate:expired){var current=reservations.findById(candidate.getId()).orElse(null);if(current!=null&&current.getState()==ReservationState.RESERVED&&!current.getExpiresAt().isAfter(now)){transition(current.getId().value(),false);released++;}}return released;}
    public Instant extendReservationsForPayment(UUID orderId,Instant minimumExpiry){if(minimumExpiry==null||!minimumExpiry.isAfter(Instant.now()))throw new IllegalArgumentException("Payment reservation expiry must be in the future");int remainder=minimumExpiry.getNano()%1_000;minimumExpiry=minimumExpiry.truncatedTo(java.time.temporal.ChronoUnit.MICROS).plusNanos(remainder==0?0:1_000);var candidates=reservations.findByOrder(orderId);if(candidates.isEmpty())throw new CatalogNotFoundException("No stock reservation exists for order: "+orderId);Instant now=Instant.now();Instant expiry=minimumExpiry;for(var candidate:candidates){stock.lockOrCreate(candidate.getWarehouseId(),candidate.getSellableId());var current=reservations.findById(candidate.getId()).orElseThrow(()->new CatalogNotFoundException("Reservation not found: "+candidate.getId().value()));if(current.getState()!=ReservationState.RESERVED||!current.getExpiresAt().isAfter(now))throw new IllegalStateException("Order stock reservation has expired or is no longer reservable");if(current.getExpiresAt().isBefore(minimumExpiry)){current.extendExpiry(minimumExpiry);reservations.save(current);}if(current.getExpiresAt().isBefore(expiry))expiry=current.getExpiresAt();}return expiry;}
    @Transactional(readOnly=true) public List<ReservationView> reservationsByOrder(UUID order){return reservations.findByOrder(order).stream().map(ReservationView::from).toList();}
    private ReservationView transition(UUID id,boolean allocate){var initial=reservations.findById(new ReservationId(id)).orElseThrow(()->new CatalogNotFoundException("Reservation not found: "+id));var level=stock.lockOrCreate(initial.getWarehouseId(),initial.getSellableId());var reservation=reservations.findById(new ReservationId(id)).orElseThrow(()->new CatalogNotFoundException("Reservation not found: "+id));var target=allocate?ReservationState.ALLOCATED:ReservationState.RELEASED;if(reservation.getState()==target)return ReservationView.from(reservation);var remaining=reservation.remainingQuantity();if(allocate){level.allocate(new Quantity(remaining));reservation.allocate();}else{level.release(new Quantity(remaining));reservation.release();}stock.save(level);reservations.save(reservation);return ReservationView.from(reservation);}
    private Warehouse warehouse(UUID id){return warehouses.findById(new WarehouseId(id)).orElseThrow(()->new CatalogNotFoundException("Warehouse not found: "+id));}
    public record WarehouseRequest(String code,String name,String location){}
    public record LowStockPolicyRequest(BigDecimal threshold,boolean active){}
    public record ReserveRequest(UUID orderId,UUID warehouseId,UUID sellableId,BigDecimal quantity){}
    public record WarehouseView(UUID id,String code,String name,String location,boolean active){static WarehouseView from(Warehouse w){return new WarehouseView(w.getId().value(),w.getCode(),w.getName(),w.getLocation(),w.isActive());}}
    public record StockView(UUID warehouseId,UUID sellableId,BigDecimal onHand,BigDecimal reserved,BigDecimal available){static StockView from(StockLevel s){return new StockView(s.getWarehouseId().value(),s.getSellableId(),s.getOnHand(),s.getReserved(),s.available());}}
    public record LowStockPolicyView(UUID warehouseId,UUID sellableId,BigDecimal threshold,boolean active){static LowStockPolicyView from(LowStockPolicy p){return new LowStockPolicyView(p.warehouseId().value(),p.sellableId(),p.threshold(),p.active());}}
    public record LowStockView(UUID warehouseId,UUID sellableId,BigDecimal available,BigDecimal threshold){}
    public record ReservationView(UUID id,UUID orderId,UUID warehouseId,UUID sellableId,BigDecimal quantity,BigDecimal allocatedQuantity,BigDecimal remainingQuantity,ReservationState state,Instant expiresAt){
        public ReservationView(UUID id,UUID orderId,UUID warehouseId,UUID sellableId,BigDecimal quantity,ReservationState state,Instant expiresAt){this(id,orderId,warehouseId,sellableId,quantity,state==ReservationState.ALLOCATED?quantity:BigDecimal.ZERO,state==ReservationState.RESERVED?quantity:BigDecimal.ZERO,state,expiresAt);}
        static ReservationView from(Reservation r){return new ReservationView(r.getId().value(),r.getOrderId(),r.getWarehouseId().value(),r.getSellableId(),r.getQuantity(),r.getAllocatedQuantity(),r.remainingQuantity(),r.getState(),r.getExpiresAt());}}
}
